INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('murudeshwar', 2, 5, 'go',
  'Driest month. 23-32C. Statue and gopuram views year-cleanest. Hotel rates ease 15 percent.',
  'February is the cleanest coastal Karnataka window. Rainfall under 5mm. Shiva statue photograph light at peak. Netrani snorkelling visibility 12-22m. Hotel rates 15 percent below January.',
  NULL,
  'Murudeshwar in February is the technical peak of the temple-statue-beach year. Rainfall under 5mm, daytime 23-32C, nights 22C, humidity 60 percent — the lowest of the year. The 123ft (37m) Shiva statue on Kanduka Hill headland at year-clearest photograph light. The 20-story gopuram (237ft, the temple trust''s claim of tallest temple gopuram in the world — disputed by some scholars, but the structural height is verifiable, the lift to the 18th floor at ₹15 ticket, 9am-5pm) runs at year-cleanest visibility from the top. The Atmalinga-shard temple — per Skanda Purana, when Ganesha tricked Ravana into setting down the Atmalinga at Gokarna, the cloth covering the linga was thrown to Murudeshwar; a piece of the linga itself is said to be embedded here, making Murudeshwar one of the linked Shiva-coast pilgrimage stops with Gokarna — at full darshan schedule (6am-1pm/3-8.30pm). Maha Shivaratri (February 15, 2026 — verify lunar date) brings 25,000-50,000 pilgrims for 24 hours; book temple accommodation 4-6 weeks ahead. The headland beach below the statue at peak bathable.'
)
