INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('murudeshwar', 3, 5, 'go',
  'Netrani peak begins. 24-33C, humidity 70 percent. Visibility 18-25m. Hotel rates 25 percent off February.',
  'March is when Netrani Island snorkelling visibility peaks at 18-25m — the year-best scuba window. Statue and gopuram photograph light still clean. Hotel rates 25 percent below February.',
  NULL,
  'Murudeshwar in March is when Netrani Island delivers its year-peak scuba conditions. Daytime 25-33C, nights 23C, humidity climbing to 70 percent in the last fortnight, rainfall under 20mm, but the Arabian Sea visibility around Netrani opens to 18-25m — the year-best window for the basalt-pinnacle dive sites at the offshore Eagle Island. Dreamz Diving, Murudeshwar Scuba School, Manta Diving (the three NAUI/PADI operators based at Murudeshwar) book full daily trips (₹3,500-5,000 per person all-in, 7am-3pm). The 90-minute boat ride from Murudeshwar jetty to Netrani 40km offshore returns 2-3 dives in waters that hold whale shark (rare, but documented), manta ray, hawksbill turtle, parrotfish, lionfish, moray eel. The 123ft (37m) Shiva statue on Kanduka Hill at year-cleanest weekday visitor load. The 20-story gopuram (237ft, lift ₹15) holds full schedule. The Atmalinga-shard temple (6am-1pm/3-8.30pm) at full schedule. The headland beach below the statue at year-cleanest swim. Holi long weekend brings a 3-day domestic bump. Hotel rates 25 percent below February: RN Shetty Resort ₹3-4.5k, Naveen Beach Resort ₹2.2-3.3k, town hotels ₹1.2-2k.'
)
