INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('murudeshwar', 4, 4, 'go',
  'Netrani peak continues. 27-34C, humidity 78 percent. Visibility 20-25m. Land trip narrows to early/late.',
  'April is when Netrani Island scuba visibility peaks — 20-25m, year-best. Heat at 30C+ collapses the land trip mid-day. Statue viewable dawn and dusk only. Hotel rates 30 percent below February.',
  NULL,
  'Murudeshwar in April is the year-best Netrani Island scuba window with the land-side heat compromise. Daytime 28-34C, nights 25C, humidity 78 percent, sea temperature 30C — bathable but hot. Netrani Island (40km offshore, dome-shaped Eagle Island) visibility hits 20-25m peak — Dreamz Diving, Murudeshwar Scuba School, Manta Diving book full daily trips through April, the calm-sea pre-monsoon window the year''s prime dive month. Operators: ₹3,500-5,000 per person all-in, 7am-3pm trips (90-min boat each way, 2-3 dives at the basalt-pinnacle sites). On land, the trip narrows. The 123ft (37m) Shiva statue on Kanduka Hill viewable comfortably 6.30-9am and 5-7pm — mid-day glare and heat make the unshaded statue plaza brutal. The 20-story gopuram (237ft, lift ₹15, 9am-5pm) interior holds at 28C — the lift to the 18th floor is the AC retreat. The Atmalinga-shard temple (6am-1pm/3-8.30pm darshan) is AC inside. The headland beach below the statue 6-9am and 5-7pm only. Vishu (April 14, Kerala spillover) brings a 2-3 day domestic bump. Hotel rates 30 percent below February peak: RN Shetty Resort ₹2.5-4k, Naveen Beach Resort ₹2-3k, town hotels ₹1-1.8k.'
)
