INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('murudeshwar', 5, 3, 'wait',
  'Late Netrani window first 10 days. 28-34C humidity 82 percent. Scuba operators close mid-month.',
  'Early May is the last Netrani Island scuba window — first 10 days extend April. Scuba operators suspend mid-month for monsoon. Heat collapses statue plaza mid-day. Hotel rates at year-low.',
  'May splits — first 10 days extend April for Netrani scuba, last 20 days pre-monsoon stress. Statue plaza brutal mid-day, beach swim risky after the third week. October-March is dramatically better.',
  'May in Murudeshwar splits cleanly in two. The first 10 days extend April: Netrani Island scuba operations continue with visibility 15-22m, sea temperature 30C, daytime 29-34C, humidity 80 percent. By May 12-15 the three operators (Dreamz Diving, Murudeshwar Scuba School, Manta Diving) suspend operations for the southwest monsoon — next restart late October. Pre-monsoon thunderstorms hit the third and fourth weeks — afternoon squalls that knock grid power 1-2 hours and raise humidity to 90 percent. The 123ft (37m) Shiva statue on Kanduka Hill viewable 6.30-9am and 5-7pm only. The 20-story gopuram (237ft, lift ₹15, 9am-5pm) at year-low visitor load. The Atmalinga-shard temple (6am-1pm/3-8.30pm) holds full schedule. The headland beach swim risky from the third week — pre-monsoon swell brings rip-current advisories. Hotel rates at year-low: RN Shetty Resort ₹2.2-3.5k, Naveen Beach Resort ₹1.8-2.8k, town hotels ₹900-1600. Konkan Railway Murudeshwar station inbound traffic at year-low. Wait for late October.'
)
