INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('murudeshwar', 6, 1, 'skip',
  'SW monsoon onset. 24-29C, 900-1100mm rainfall. Netrani closed, beach forbidden. Statue viewable wet. Skip.',
  NULL,
  'June is when the southwest monsoon hits Murudeshwar with peak coastal Karnataka force. Rainfall 900-1100mm, Netrani Island scuba closed for season, beach forbidden, statue plaza wet. Skip.',
  'June in Murudeshwar is the southwest monsoon''s arrival point. The current hits the coastal Karnataka shoreline within 24-48 hours of the IMD Thiruvananthapuram announcement. Rainfall jumps to 900-1100mm across 24-26 wet days. Daytime 25-29C feels mild but 92 percent humidity and sustained 6-12 hour downpours close the snorkelling-statue-beach trip. Netrani Island scuba and snorkelling operations suspended for monsoon — Dreamz Diving, Murudeshwar Scuba School, Manta Diving closed for the season (next restart late October). The headland beach below the Shiva statue under Karnataka Tourism red-flag advisory — sea bathing prohibited, lifeguards withdrawn. The 123ft (37m) Shiva statue on Kanduka Hill remains viewable from the temple complex grounds (though the unshaded plaza is wet most days). The 20-story gopuram (237ft, lift ₹15, 9am-5pm) holds its hours — the AC interior is the one reliable shape. The Atmalinga-shard temple (6am-1pm/3-8.30pm darshan) continues full operations. Hotel rates at year-low: RN Shetty Resort ₹2-3.2k, Naveen Beach Resort ₹1.5-2.5k, town hotels ₹800-1400. Konkan Railway Murudeshwar station landslide-watch mode.'
)
