INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('murudeshwar', 7, 1, 'skip',
  'Peak monsoon. 24-28C, 1000-1200mm rainfall. Netrani closed, beach forbidden. Skip.',
  NULL,
  'July is the wettest month at Murudeshwar. Rainfall 1000-1200mm. Netrani scuba closed, beach forbidden. Konkan Railway landslide-watch. Skip outright Skip until weather window opens.',
  'July in Murudeshwar is the year''s wettest stretch. Rainfall averages 1100mm across 26-28 wet days, often as 6-12 hour sustained deluges. Daytime 25-28C, humidity 93 percent. Netrani Island scuba operations suspended for monsoon. The headland beach below the Shiva statue under Karnataka Tourism red-flag advisory — sea bathing prohibited, lifeguards withdrawn. The 123ft (37m) Shiva statue on Kanduka Hill viewable from the wet plaza — the statue itself stands firm in monsoon weather but photographs read drab against grey-sky. The 20-story gopuram (237ft, lift ₹15, 9am-5pm) is the one reliable AC option — the lift to the 18th floor returns an above-the-rain panorama on lighter-rain days. The Atmalinga-shard temple (per Skanda Purana, the piece of the Atmalinga thrown to Murudeshwar by Ganesha when Ravana set the parent linga down at Gokarna) holds full darshan operations 6am-1pm/3-8.30pm. Konkan Railway Murudeshwar station at peak landslide-watch — multiple cancellations through the month. Hotel rates year-low: RN Shetty Resort ₹2-3k, Naveen Beach Resort ₹1.5-2.5k, town hotels ₹700-1300. Wait for late October.'
)
