INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('murudeshwar', 8, 1, 'skip',
  'Monsoon continues. 24-29C, 600-800mm rainfall. Netrani closed, beach forbidden. Skip.',
  NULL,
  'August holds July''s pattern. Netrani still closed, beach forbidden. Krishna Janmashtami (Aug 25, 2026 — verify) brings minor temple bump but standard trip skip.',
  'August in Murudeshwar holds the July monsoon pattern with marginally fewer extreme-rain days. Rainfall 600-800mm across 23-25 wet days. Daytime 25-29C feels mild but constant rain and 91 percent humidity strip outdoor activity. Netrani Island scuba operations suspended for monsoon. The headland beach remains under Karnataka Tourism red-flag advisory — sea bathing prohibited. The 123ft (37m) Shiva statue on Kanduka Hill viewable from the wet plaza in lighter-rain windows. The 20-story gopuram (237ft, lift ₹15, 9am-5pm) holds its hours as the one reliable AC option. The Atmalinga-shard temple (6am-1pm/3-8.30pm darshan) at full daily operations. Krishna Janmashtami (variable late-August date, 2026 verify against lunar calendar — typically 4-5 days before the new moon of Bhadrapada) brings a minor temple-festival bump but Murudeshwar is Shiva-anchored, not Krishna-anchored — the Janmashtami draw is at Udupi 100km south, not here. Konkan Railway still landslide-watch but cancellation events ease in the second half. Hotel rates year-low: RN Shetty Resort ₹2-3.2k, Naveen Beach Resort ₹1.7-2.7k, town hotels ₹800-1400. The next clean window is mid-October.'
)
