INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('murudeshwar', 9, 2, 'wait',
  'Monsoon retreat. 24-30C, 300-400mm rain. Netrani scuba prep for October. Beach reopening late month.',
  'September is the recovery month. SW monsoon retreats around Sep 25, beach reopens late month, Netrani scuba operators prep for October restart. Late September workable but October 15 onward dramatically cleaner.',
  'September is on the way back but first fortnight remains wet, Netrani scuba still suspended, beach swim under advisory through three weeks. Push to mid-October.',
  'September in Murudeshwar is the trickle back from monsoon. Rainfall drops to 300-400mm across 16-18 wet days, mostly the first fortnight. Daytime 25-30C, humidity easing to 82 percent in the second half. The southwest monsoon retreats from coastal Karnataka around September 25-30 (IMD declares formal withdrawal). The headland beach below the Shiva statue remains under Karnataka Tourism advisory through the first three weeks; coast guard typically lifts the red flag by the last week. Netrani Island scuba operators (Dreamz Diving, Murudeshwar Scuba School, Manta Diving) prepare for October 1 restart — visibility check dives from the last week of September. The 123ft (37m) Shiva statue on Kanduka Hill returns to clean dawn-and-dusk photograph conditions. The 20-story gopuram (237ft, lift ₹15, 9am-5pm) at returning weekday visitor load. The Atmalinga-shard temple (6am-1pm/3-8.30pm) at full schedule — pilgrim flow recovering after monsoon. Hotel rates climb 15-20 percent versus August lows: RN Shetty Resort ₹2.5-4k, Naveen Beach Resort ₹2-3.2k, town hotels ₹1-1.8k. The October 15 onward window is dramatically cleaner.'
)
