INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('murudeshwar', 10, 4, 'go',
  'Season opens. 24-31C, 200-250mm spillover. Netrani scuba restarts. Statue and beach back to clean.',
  'October is the season opener. Late-monsoon residue first 10 days, then full Netrani-statue-beach mode. Scuba operators restart Sep-May season. Hotel rates 25 percent below January.',
  NULL,
  'October in Murudeshwar is the proper return to coherent. Rainfall drops to 200-250mm with the bulk falling in the first ten days; from October 15 onward Murudeshwar flips into clean statue-temple-scuba mode. Daytime 25-31C, humidity falling from 85 to 75 percent. The headland beach below the Shiva statue reopens to swimming as coast guard lifts the monsoon red-flag — water temperature 28C, sea swell easing. Netrani Island scuba operators (Dreamz Diving, Murudeshwar Scuba School, Manta Diving) restart their October-May season — visibility 10-18m through October, building toward the March-May peak. ₹3,500-5,000 per person all-in, 7am-3pm trips. The 123ft (37m) Shiva statue on Kanduka Hill at year-cleanest post-monsoon viewing. The 20-story gopuram (237ft, lift ₹15, 9am-5pm) at recovering weekday visitor load. The Atmalinga-shard temple (per Skanda Purana, the piece of Ravana''s Atmalinga thrown to Murudeshwar by Ganesha when the parent linga rooted at Gokarna) holds 6am-1pm/3-8.30pm darshan. Karnataka Rajyotsava preparation begins for November 1. Hotel rates 25 percent below January peak: RN Shetty Resort ₹3-4.5k, Naveen Beach Resort ₹2.3-3.5k, town hotels ₹1.2-2.2k.'
)
