INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('murudeshwar', 11, 5, 'go',
  'Peak builds. 23-31C, rainfall under 60mm. Karnataka Rajyotsava Nov 1. Hotel rates climb 20 percent.',
  'November is the proper pivot to peak. Rainfall under 60mm, full statue-beach-scuba weather. Karnataka Rajyotsava Nov 1. Netrani visibility 10-20m. Hotel rates climb 20 percent.',
  NULL,
  'November in Murudeshwar is the year''s second-peak month behind January. Rainfall drops under 60mm, daytime 24-31C, sea breeze cooling evenings to 22-23C, humidity dropping below 70 percent. The headland beach below the Shiva statue at full bathable conditions — water 27C, sea-state green flag. Netrani Island scuba operations at full October-May tempo, visibility 10-20m through November, building toward March-May peak. Dreamz Diving, Murudeshwar Scuba School, Manta Diving at ₹3,500-5,000 per person all-in, 7am-3pm trips. The 123ft (37m) Shiva statue on Kanduka Hill at year-clearest photograph light — the second-best month after February for the silhouette-against-Arabian-Sea shot. The 20-story gopuram (237ft, lift ₹15, 9am-5pm) at full weekday-weekend tempo. The Atmalinga-shard temple (the Murudeshwar piece of Ravana''s Atmalinga per Skanda Purana — the parent linga rooted at Gokarna 70km south) holds 6am-1pm/3-8.30pm darshan. Karnataka Rajyotsava (November 1, 1956 state formation under States Reorganisation Act) sees cultural programmes.'
)
