INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('murudeshwar', 12, 5, 'go',
  'Peak season. 22-31C dry. Christmas-NYE rates 1.8x. Statue silhouette, gopuram views, scuba all at peak.',
  'December is when Murudeshwar runs at full capacity. Christmas-NYE rates 1.8x normal. Statue silhouette at year-iconic photograph light. Lock RN Shetty Resort rooms 4-6 weeks ahead.',
  NULL,
  'December in Murudeshwar is the operational peak and the most coherent stretch of the temple-statue-beach year. Daytime 23-31C, nights 22C, rainfall under 30mm. The Christmas-NYE corridor (December 22 to January 5) sees rates run 1.8x the November baseline: RN Shetty Resort ₹5-7k (the on-headland property closest to the Shiva statue and gopuram), Naveen Beach Resort ₹4-5.5k, town hotels ₹2-3k. The 123ft (37m) Shiva statue on Kanduka Hill at year-cleanest silhouette photograph light — 5.30-6.30pm winter sunset against the Arabian Sea is the year-iconic shot. The 20-story gopuram (237ft, lift ₹15, 9am-5pm) at peak weekend traffic — go on a weekday morning. The Atmalinga-shard temple (one of the linked Shiva-coast pilgrimage stops with Gokarna — per Skanda Purana the piece of Ravana''s Atmalinga thrown to Murudeshwar by Ganesha) at peak December pilgrim flow ahead of Maha Shivaratri (February 2026). 6am-1pm/3-8.30pm darshan. The headland beach at peak swim weather — water 27C, no sea-state advisories. Netrani Island scuba at visibility 10-20m — Dreamz Diving, Murudeshwar Scuba School, Manta Diving at full operations, book a day ahead through Christmas-NYE corridor.'
)
